begin;
create table if not exists public.frc_parts_inventory(id uuid primary key default gen_random_uuid(),name text not null,category text not null,part_number text,quantity numeric(12,2) not null default 0 check(quantity>=0),minimum_quantity numeric(12,2) not null default 0 check(minimum_quantity>=0),unit text not null default 'pcs',location text,supplier text,unit_cost numeric(12,2) check(unit_cost is null or unit_cost>=0),notes text,archived boolean not null default false,created_by uuid references public.team_members(id) on delete set null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.frc_stock_movements(id uuid primary key default gen_random_uuid(),part_id uuid not null references public.frc_parts_inventory(id) on delete cascade,quantity_delta numeric(12,2) not null check(quantity_delta<>0),reason text not null check(reason in ('received','used','counted','returned','damaged','other')),note text,member_id uuid not null references public.team_members(id) on delete restrict default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.frc_purchase_requests(id uuid primary key default gen_random_uuid(),part_id uuid references public.frc_parts_inventory(id) on delete set null,item_name text not null,quantity numeric(12,2) not null check(quantity>0),estimated_cost numeric(12,2) check(estimated_cost is null or estimated_cost>=0),supplier text,urgency text not null default 'normal' check(urgency in ('low','normal','high','critical')),reason text not null,status text not null default 'requested' check(status in ('requested','approved','ordered','received','rejected','cancelled')),requested_by uuid not null references public.team_members(id) on delete restrict default auth.uid(),reviewed_by uuid references public.team_members(id) on delete set null,reviewed_at timestamptz,ordered_at timestamptz,received_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists frc_parts_search_idx on public.frc_parts_inventory(category,archived,name);create index if not exists frc_stock_part_idx on public.frc_stock_movements(part_id,created_at desc);create index if not exists frc_purchase_status_idx on public.frc_purchase_requests(status,urgency,created_at desc);
alter table public.frc_parts_inventory enable row level security;alter table public.frc_stock_movements enable row level security;alter table public.frc_purchase_requests enable row level security;
drop policy if exists "members view frc parts" on public.frc_parts_inventory;create policy "members view frc parts" on public.frc_parts_inventory for select to authenticated using(public.current_team_role() is not null);drop policy if exists "admins manage frc parts" on public.frc_parts_inventory;create policy "admins manage frc parts" on public.frc_parts_inventory for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members view stock movements" on public.frc_stock_movements;create policy "members view stock movements" on public.frc_stock_movements for select to authenticated using(public.current_team_role() is not null);drop policy if exists "members record stock movements" on public.frc_stock_movements;create policy "members record stock movements" on public.frc_stock_movements for insert to authenticated with check(member_id=auth.uid() and public.current_team_role() is not null);
drop policy if exists "members view purchase requests" on public.frc_purchase_requests;create policy "members view purchase requests" on public.frc_purchase_requests for select to authenticated using(public.current_team_role() is not null);drop policy if exists "members request purchases" on public.frc_purchase_requests;create policy "members request purchases" on public.frc_purchase_requests for insert to authenticated with check(requested_by=auth.uid() and public.current_team_role() is not null);drop policy if exists "admins manage purchases" on public.frc_purchase_requests;create policy "admins manage purchases" on public.frc_purchase_requests for update to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.adjust_frc_part_stock(target_part uuid,amount numeric,movement_reason text,movement_note text default null) returns numeric language plpgsql security definer set search_path=public as $$declare new_quantity numeric;begin if public.current_team_role() is null then raise exception 'Active team membership required';end if;update public.frc_parts_inventory set quantity=greatest(0,quantity+amount),updated_at=now() where id=target_part returning quantity into new_quantity;if new_quantity is null then raise exception 'Part not found';end if;insert into public.frc_stock_movements(part_id,quantity_delta,reason,note,member_id) values(target_part,amount,movement_reason,movement_note,auth.uid());return new_quantity;end$$;grant execute on function public.adjust_frc_part_stock(uuid,numeric,text,text) to authenticated;
commit;
